 ?><div class="notice mb">In-app notifications are immediate. Email and SMS delivery uses this queue. “Sent” means the provider accepted the message; it does not confirm delivery to the recipient’s device or inbox.</div><div class="flex between mb"><span class="small muted">Last scheduled workflow run: <?=e(setting('workflow_last_run','Not recorded'))?></span><?php if(can('workflow.run',$u)):?><form method="post" action="<?=e(url('admin/jobs'))?>" data-confirm="Run escalation checks and send up to 5 queued notifications now?"><?=csrf_field()?><button class="btn btn-primary" type="submit">Run workflow and delivery</button></form><?php endif;?></div><?php $states=[''=>'All states','configuration_required'=>'Configuration required','pending'=>'Pending','processing'=>'Processing','retry'=>'Retry scheduled','failed'=>'Failed','sent'=>'Provider accepted','cancelled'=>'Cancelled'];$state=(string)($_GET['state']??'');$channel=(string)($_GET['channel']??'');$search=mb_substr(trim((string)($_GET['q']??'')),0,100);$where='1=1';$params=[];if($state!==''&&isset($states[$state])){$where.=' AND o.state=?';$params[]=$state;}if(in_array($channel,['email','sms'],true)){$where.=' AND o.channel=?';$params[]=$channel;}if($search!==''){$where.=' AND (u.name LIKE ? OR o.recipient LIKE ? OR o.subject LIKE ?)';array_push($params,'%'.$search.'%','%'.$search.'%','%'.$search.'%');}$total=(int)value('SELECT COUNT(*) FROM outbox o JOIN users u ON u.id=o.user_id WHERE '.$where,$params);$pages=max(1,(int)ceil($total/50));$page=min($pages,max(1,(int)($_GET['page']??1)));$offset=($page-1)*50;panel_start('Delivery records','<span class="small">'.$total.' matching records</span>');?><form class="filters" method="get" action="<?=e(url('admin/outbox'))?>"><?php field('q','Recipient or subject',$search,'search','maxlength="100"');select_field('state','Delivery state',$states,$state);select_field('channel','Channel',[''=>'All channels','email'=>'Email','sms'=>'SMS'],$channel);?><button class="btn btn-outline" type="submit">Filter</button><a class="btn btn-outline" href="<?=e(url('admin/outbox'))?>">Clear</a></form><?php $items=rows('SELECT o.*,u.name user_name FROM outbox o JOIN users u ON u.id=o.user_id WHERE '.$where.' ORDER BY o.id DESC LIMIT 50 OFFSET '.$offset,$params);if(!$items)empty_state('No delivery records yet','Notifications are queued when requests are submitted or updated.');else{?><div class="table-responsive"><table class="table"><thead><tr><th>Recipient / subject</th><th>Channel</th><th>State</th><th>Attempts</th><th>Provider response</th><th></th></tr></thead><tbody><?php foreach($items as $m):?><tr><td><strong><a href="<?=e(url('admin/outbox/detail?id='.$m['id']))?>"><?=e($m['user_name'])?></a></strong><small class="block"><?=e($m['recipient'])?></small><small class="block"><?=e($m['subject'])?></small></td><td><?=e(label($m['channel']))?></td><td><?=badge($m['state'])?></td><td><?=(int)$m['attempts']?></td><td><?=e($m['last_error']?:($m['provider_id']?:'Awaiting delivery'))?><small class="block"><?=e(dates($m['sent_at']??$m['created_at'],true))?></small></td><td><?php if(can('outbox.manage',$u)&&in_array($m['state'],['configuration_required','failed','retry','pending'],true)):?><form method="post" action="<?=e(url('admin/outbox/retry'))?>"><?=csrf_field()?><input type="hidden" name="id" value="<?=(int)$m['id']?>"><button class="btn btn-outline btn-sm" type="submit">Requeue</button></form><form method="post" action="<?=e(url('admin/outbox/cancel'))?>" data-confirm="Cancel this queued delivery?"><?=csrf_field()?><input type="hidden" name="id" value="<?=(int)$m['id']?>"><button class="btn btn-outline btn-sm" type="submit">Cancel</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php }?><div class="pagination"><span>Page <?=$page?> of <?=$pages?></span><?php foreach(['Previous'=>$page-1,'Next'=>$page+1]as $text=>$n)if($n>=1&&$n<=$pages){$query=$_GET;$query['page']=$n;?><a class="btn btn-outline btn-sm" href="<?=e(url('admin/outbox?'.http_build_query($query)))?>"><?=e($text)?></a><?php }?></div><?php panel_end();
