function settings_page_body(): void {
 ?><form method="post" action="<?=e(url('admin/settings'))?>"><?=csrf_field()?><div class="stack"><div class="grid grid-2"><?php panel_start('Workspace identity');field('app_name','Display name',setting('app_name','CivicFlow'),'text','required maxlength="70"');field('organisation_name','Operating organisation',setting('organisation_name','CivicFlow'),'text','required maxlength="160"');field('support_email','Public support email',setting('support_email'),'email','maxlength="190"');?><label class="checkbox"><input type="checkbox" name="staff_mfa_required" value="1" <?=setting('staff_mfa_required','0')==='1'?'checked':''?>> Require two-factor authentication for every staff account</label><?php field('app_tagline','Tagline',setting('app_tagline','Public services. Clear progress.'),'text','required maxlength="120"');?><p class="small muted">The workspace emblem lives in assets/img/logo.svg. Use an organisation-owned emblem rather than an unrelated institution’s identity.</p><?php panel_end();panel_start('Deployment health');?><dl class="detail-meta"><div><dt>PHP</dt><dd><?=e(PHP_VERSION)?></dd></div><div><dt>Database</dt><dd><?=e(cfg('database')['driver'])?></dd></div><div><dt>Installer</dt><dd>Locked</dd></div><div><dt>HTTPS required</dt><dd><?=cfg('force_https')?'Yes':'No'?></dd></div><div><dt>cURL</dt><dd><?=extension_loaded('curl')?'Available':'Not installed'?></dd></div><div><dt>Uploads writable</dt><dd><?=is_writable(ROOT.'/storage/uploads')?'Yes':'No'?></dd></div></dl><p class="small muted mt">Use a valid SSL certificate and back up the database, private uploads and config/local.php together.</p><?php panel_end();?></div><div class="grid grid-2"><?php panel_start('Email notifications');?><label class="checkbox"><input name="email_enabled" type="checkbox" value="1" <?=setting('email_enabled')==='1'?'checked':''?>> Enable SMTP email delivery</label><?php field('smtp_host','SMTP host',setting('smtp_host'));field('smtp_port','SMTP port',setting('smtp_port','587'),'number','min="1" max="65535"');select_field('smtp_security','Encryption',['tls'=>'STARTTLS — normally port 587','ssl'=>'Implicit TLS — normally port 465'],setting('smtp_security','tls'));field('smtp_username','SMTP username',setting('smtp_username'));field('smtp_from','Sender email',setting('smtp_from'),'email');field('smtp_password','SMTP password — leave blank to retain','','password','autocomplete="new-password"');?><small class="muted">Stored credential: <?=secret('smtp_password')!==''?'configured':'not configured'?></small><label class="checkbox"><input name="clear_smtp_password" type="checkbox" value="1"> Remove stored SMTP password</label><p class="small muted">Use a mailbox or SMTP relay authorised to send from your domain. Verify SPF and DKIM with your mail provider.</p><?php panel_end();panel_start('SMS notifications');?><label class="checkbox"><input name="sms_enabled" type="checkbox" value="1" <?=setting('sms_enabled')==='1'?'checked':''?>> Enable Termii SMS delivery</label><?php field('sms_base_url','Account API base URL',setting('sms_base_url'),'url','placeholder="HTTPS base URL from your Termii account"');field('sms_sender','Approved sender ID',setting('sms_sender','CivicFlow'),'text','maxlength="11"');select_field('sms_channel','SMS route',['generic'=>'Generic','dnd'=>'DND / transactional'],setting('sms_channel','generic'));field('sms_api_key','Termii API key — leave blank to retain','','password','autocomplete="new-password"');?><small class="muted">Stored credential: <?=secret('sms_api_key')!==''?'configured':'not configured'?></small><label class="checkbox"><input name="clear_sms_api_key" type="checkbox" value="1"> Remove stored SMS key</label><p class="small muted">An approved sender and funded provider account are required. Nigerian local numbers are normalised to international format for sending.</p><?php panel_end();?></div><div class="grid grid-2"><?php panel_start('AI citizen assistance');?><label class="checkbox"><input name="ai_enabled" type="checkbox" value="1" <?=setting('ai_enabled')==='1'?'checked':''?>> Enable OpenAI assistance</label><?php field('ai_model','Available model ID',setting('ai_model'),'text','maxlength="100" placeholder="Enter a Responses-compatible model from your account"');field('ai_api_key','OpenAI API key — leave blank to retain','','password','autocomplete="new-password"');?><small class="muted">Stored credential: <?=secret('ai_api_key')!==''?'configured':'not configured'?></small><label class="checkbox"><input name="clear_ai_api_key" type="checkbox" value="1"> Remove stored AI key</label><p class="small muted">Uses the Responses API with storage disabled. Only the question and service facts are sent. The local service guide remains available without an API key and is labelled separately from AI responses.</p><?php panel_end();panel_start('Scheduled workflows');?><p class="small">Add the following command in cPanel Cron Jobs to run every five minutes. Replace the PHP executable with the PHP 8.2+ path provided by your host.</p><pre class="diagnostic">*/5 * * * * /usr/local/bin/php <?=e(ROOT)?>/cron/run.php</pre><p class="small muted">The job escalates overdue requests once, retries delivery with backoff and records the latest run. A private file lock prevents overlapping delivery jobs. You can also run it from Notification delivery.</p><p class="small muted">Integration credentials are encrypted in the database using the installation key in config/local.php. Blank password fields keep existing values.</p><?php panel_end();?></div><div class="actions"><button class="btn btn-primary" type="submit">Save configuration</button><a class="btn btn-outline" href="<?=e(url('admin/outbox'))?>">View notification delivery</a></div></div></form><?php
}
